package org.apache.commons.math.fraction;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class Fraction_compareTo_TriageGen1Test {

    @Test
    public void testCompareTo_Less() {
        Fraction f1 = new Fraction(1, 3); // 0.333...
        Fraction f2 = new Fraction(1, 2); // 0.5

        int result = f1.compareTo(f2);

        assertEquals("1/3 should be less than 1/2", -1, result);
    }

    @Test
    public void testCompareTo_Greater() {
        Fraction f1 = new Fraction(3, 4); // 0.75
        Fraction f2 = new Fraction(1, 4); // 0.25

        int result = f1.compareTo(f2);

        assertEquals("3/4 should be greater than 1/4", 1, result);
    }

    @Test
    public void testCompareTo_Equal() {
        Fraction f1 = new Fraction(1, 2);
        Fraction f2 = new Fraction(2, 4); // Mathematically equal

        int result = f1.compareTo(f2);

        assertEquals("1/2 should be equal to 2/4", 0, result);
    }

    @Test
    public void testCompareTo_NegativeValues() {
        Fraction f1 = new Fraction(-1, 2); // -0.5
        Fraction f2 = new Fraction(1, 2);  // 0.5

        int resultLess = f1.compareTo(f2);
        assertEquals("-0.5 should be less than 0.5", -1, resultLess);

        int resultGreater = f2.compareTo(f1);
        assertEquals("0.5 should be greater than -0.5", 1, resultGreater);
    }

    @Test
    public void testCompareTo_Zero() {
        Fraction f1 = new Fraction(0, 1);
        Fraction f2 = new Fraction(0, 5);
        Fraction f3 = new Fraction(1, 1);

        assertEquals("0 should be equal to 0", 0, f1.compareTo(f2));
        assertEquals("0 should be less than 1", -1, f1.compareTo(f3));
        assertEquals("0 should be greater than -1", 1, f1.compareTo(new Fraction(-1, 1)));
    }

    @Test
    public void testCompareTo_FloatingPointPrecision() {
        // Testing behavior with double precision edge cases
        Fraction f1 = new Fraction(1, 3); 
        Fraction f2 = new Fraction(1, 3);

        assertEquals("Identical fractions should return 0", 0, f1.compareTo(f2));
    }
}
